   const res=await fetch("https://openrouter.ai/api/v1/key",{headers:{authorization:"Bearer "+key,accept:"application/json"},redirect:"manual",signal:AbortSignal.timeout(5000)});
   if(!res.ok)throw Error("quota unavailable");
