   return {code:"QUOTA",message:"服务商确认 API 可用额度不足（"+status+"），请检查该渠道的余额及项目额度"};
  if(status===402)return {code:"BILLING",message:"服务商拒绝计费请求（402），请检查该渠道的余额或密钥消费限额"};
