/* POST SSE: real upstream deltas where supported; terminal event commits the exact persisted answer. */
function chatStream(req,env,user){
 const encoder=new TextEncoder();
 const stream=new ReadableStream({
  async start(controller){
   const send=(event)=>{try{controller.enqueue(encoder.encode("data: "+JSON.stringify(event)+"\n\n"))}catch{}};
   try{
    const result=await reservedSubmission(req,env,user,"chat",()=>chat(req,env,user,token=>send({type:"delta",text:token})));
    send({type:"done",chatId:result.chatId,userMessageId:result.userMessageId,assistantMessageId:result.assistantMessageId,reply:result.reply,images:result.images||[],createdAt:result.createdAt,model:result.model,usedModel:result.usedModel,provider:result.provider,freeFallback:result.freeFallback===true,primarySucceeded:result.primarySucceeded===true,primaryFailure:result.primaryFailure||null,usage:result.usage||null,incomplete:result.incomplete,mediaMode:result.mediaMode,requestId:result.requestId,pending:result.pending});
   }catch(e){send({type:"error",error:e?.message||"回复未完成",code:e?.code||null,upstreamStatus:e?.upstreamStatus||null})}
   finally{controller.close()}
  }
 });
 return new Response(stream,{headers:{"content-type":"text/event-stream; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","x-accel-buffering":"no"}});
}
async function uploadFile(req,env,user){
 requireUser(user);
 if(!env.MEDIA)throw Object.assign(new Error("文件存储未配置"),{status:503});
 if(Number(req.headers.get("content-length")||0)>8500000)throw Object.assign(new Error("附件最多8MB"),{status:413});
 const reader=req.body?.getReader();
 if(!reader)throw Error("上传文件为空");
 const parts=[];let total=0;
 for(;;){
  const {done,value}=await reader.read();if(done)break;
  total+=value.byteLength;
  if(total>8500000){await reader.cancel().catch(()=>{});throw Object.assign(new Error("附件最多8MB"),{status:413})}
  parts.push(value);
 }
 const formReq=new Request(req.url,{method:"POST",headers:{"content-type":req.headers.get("content-type")||""},body:new Blob(parts)});
 const form=await formReq.formData(),file=form.get("file");
 if(!(file instanceof File))throw Error("请选择文件");
 const originalType=String(file.type||"").toLowerCase();
 const type=(originalType==="application/octet-stream"||!originalType)&&/\.(heic|heif)$/i.test(file.name)?(/\.heif$/i.test(file.name)?"image/heif":"image/heic"):originalType;
 if(!["image/jpeg","image/png","image/webp","image/gif","image/heic","image/heif","text/plain","text/markdown","text/csv","application/pdf"].includes(type))throw Error("仅支持常见图片、PDF、TXT、MD、CSV");
 if(!file.size||file.size>8000000)throw Error("单文件上限8MB");
 const name=String(file.name||"附件").replace(/[<>\x00-\x1f]/g,"").slice(0,110)||"附件";
 const id=crypto.randomUUID();
 // Uploads use the existing authenticated, rate-limited route and bounded file size.
 await env.MEDIA.put(user.id+"/"+id,file.stream(),{httpMetadata:{contentType:type},customMetadata:{name}});
 return {ok:true,id,name,type,size:file.size,url:"/api/files/"+id};
}
